"""
    Private function for obtaining min and max indicies.
    """
def _get_min_and_index(lst: Any) -> object {
    (minval, minidx) = (lst[0], 0);
    for (i, v) in enumerate(lst[1:]) {
        if (v < minval) {
            (minval, minidx) = (v, (i + 1));
        }
    }
    return (minval, minidx);
}

